const core=[['budgets','预算首页'],['wishes','心愿首页'],['budget-detail','预算详情'],['records','消费记录'],['expense-detail','消费详情'],['calendar','消费日历'],['history-review','历史周期'],['budget-info','预算信息'],['records-layer','全部记录'],['library','弧线卡库'],['library-sphere','球面卡库'],['wish-front','心愿正面'],['wish-expanded','心愿背面'],['collection','已实现'],['collection-back','收藏背面'],['wallet','心愿余额'],['wallet-entry','余额变动'],['record','记一笔'],['create-budget','创建预算卡'],['create-wish','添加心愿'],['wish-cover','心愿封面'],['agent','小朵'],['settings','设置'],['settlement-review','结算核对'],['settlement-accepted','已勾选结算核对'],['settlement-fx','汇率核对'],['settlement-fx-accepted','已勾选汇率核对'],['redemption','购买核对'],['redemption-checked','已勾选购买核对'],['wishes-list','心愿列表'],['collection-redeemed','兑换后收藏']];
const all=[...core.map(([key,title])=>({key,title})),...EXTRA_STATES]; const lookup=new Map(all.map(s=>[s.key,s]));
const cssColor=p=>{if(p?.role){let [theme,role]=p.role.split('/');return colors[theme]?.[role]||'transparent'}if(p?.type==='GRADIENT_LINEAR')return 'linear-gradient(135deg,'+p.gradientStops.map(s=>`rgba(${Math.round(s.color.r*255)},${Math.round(s.color.g*255)},${Math.round(s.color.b*255)},${s.color.a??1}) ${s.position*100}%`).join(',')+')';if(p?.color){let c=p.color;return `rgba(${Math.round(c.r*255)},${Math.round(c.g*255)},${Math.round(c.b*255)},${p.opacity??1})`}return 'transparent'};
let routeMap=new Map();let current='budgets',currentTheme='light';
function render(n,parent,auto=false){if(!n.visible)return null;const el=document.createElement(n.type==='TEXT'?'div':'div');el.className='node '+(n.type==='TEXT'?'text':'')+(n.isButton?' action':'');el.dataset.node=n.name||'';el.dataset.id=n.id;
 const s=el.style;s.position=auto?'relative':'absolute';if(!auto){s.left=(n.x||0)+'px';s.top=(n.y||0)+'px'}s.width=n.width+'px';s.height=n.height+'px';s.boxSizing='border-box';if(n.opacity!==undefined)s.opacity=n.opacity;if(n.rotation)s.transform=`rotate(${n.rotation}deg)`;if(n.scale)s.transform=`scale(${n.scale})`;if(n.scale)s.transformOrigin='top left';if(n.cornerRadius)s.borderRadius=n.cornerRadius+'px';if(n.clipsContent)s.overflow=n.overflowDirection==='VERTICAL'?'auto':'hidden';if(n.fills?.length){let c=cssColor(n.fills[0]);if(n.type==='TEXT')s.color=c;else s.background=c}if(n.strokes?.length)s.border=`${n.strokeWeight||1}px solid ${cssColor(n.strokes[0])}`;if(n.effects?.length)s.boxShadow='0 9px 24px rgba(0,0,0,.055)';
 if(n.type==='TEXT'){el.textContent=n.characters||'';s.fontSize=(n.fontSize||17)+'px';s.fontWeight=({Bold:700,Semibold:600,Medium:500,Regular:400}[n.fontName?.style]||400);s.lineHeight=(n.lineHeight?.value||Math.ceil((n.fontSize||17)*1.38))+'px';s.height='auto';if(n.textAlignHorizontal)s.textAlign=n.textAlignHorizontal.toLowerCase();s.whiteSpace='pre-wrap'}
 if(n.asset){s.backgroundImage=`url("assets/${n.asset}")`;s.backgroundSize='100% 100%';s.backgroundRepeat='no-repeat'}if(n.svg)el.innerHTML=n.svg;
 if(n.layoutMode){s.display='flex';s.flexDirection=n.layoutMode==='VERTICAL'?'column':'row';s.gap=(n.itemSpacing||0)+'px';s.alignItems=n.counterAxisAlignItems==='CENTER'?'center':'flex-start';s.padding=[n.paddingTop||0,n.paddingRight||0,n.paddingBottom||0,n.paddingLeft||0].map(x=>x+'px').join(' ');if(n.primaryAxisSizingMode==='AUTO')s.height='auto';}
 const target=routeMap.get(n.id);if(target){el.dataset.target=target;el.setAttribute('role','button');el.tabIndex=0;el.classList.add('hotspot');el.setAttribute('aria-label',n.name||'打开')}if(n.systemAction){el.dataset.system=n.systemAction;el.setAttribute('role','button');el.tabIndex=0;el.classList.add('hotspot')}
 const isField=n.name?.startsWith('Field/');if(isField){s.display='flex';s.flexDirection='column';s.gap='6px';s.padding='12px 18px';s.minHeight='78px';s.height='auto';}
 parent.appendChild(el);for(const c of n.children)render(c,el,!!n.layoutMode||isField);return el;}
function go(key,theme){if(key==='wallet-redeemed')key='wallet-entry-redemption';if(!lookup.has(key)){showNote('此动作暂为设计占位，未连接可审阅页面。');return}current=key;if(theme)currentTheme=theme;const hash=`#${currentTheme}/${current}`;if(location.hash!==hash)history.replaceState(null,'',hash);showCurrent()}
function showNote(msg){let n=document.getElementById('notice');if(!n)return;n.textContent=msg;n.hidden=false;clearTimeout(showNote.timer);showNote.timer=setTimeout(()=>n.hidden=true,4200)}
function showCurrent(){window.scrollTo(0,0);document.documentElement.scrollTop=0;document.body.scrollTop=0;let host=document.getElementById('phone');if(!host)return;host.innerHTML='';let model=page.children.find(n=>n.name===currentTheme+'/'+current);if(model){let el=render(model,host);el.style.left='0';el.style.top='0'}document.body.dataset.theme=currentTheme;document.getElementById('mobile-page').value=current;document.getElementById('current-name').textContent=lookup.get(current)?.title||current;document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===current));document.querySelectorAll('[data-theme-choice]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.themeChoice===currentTheme)))}
function routeClick(e){const n=e.target.closest('[data-target],[data-system]');if(!n)return;if(n.dataset.system){showNote('系统动作在此原型中为设计占位，不会触发授权或执行操作。');return}let v=n.dataset.target.split('/');go(v.at(-1),v.length>1?v[0]:currentTheme)}
function sizePhone(){const wrap=document.querySelector('.phone-wrap'),stage=document.querySelector('.stage');if(!wrap||!stage)return;const stageStyle=getComputedStyle(stage);const availableWidth=stage.clientWidth-parseFloat(stageStyle.paddingLeft)-parseFloat(stageStyle.paddingRight);const widthScale=Math.min(1,Math.max(.1,availableWidth/402));const isMobile=window.matchMedia('(max-width:700px)').matches;const heightScale=Math.min(1,Math.max(.1,(window.innerHeight-wrap.getBoundingClientRect().top-20)/874));const scale=isMobile?widthScale:Math.min(widthScale,heightScale);wrap.style.width=(402*scale)+'px';wrap.style.height=(874*scale)+'px';wrap.style.setProperty('--phone-scale',scale);}
async function init(){const BATCH=['light','dark'].flatMap(theme=>all.map((s,index)=>({key:s.key,index,theme,data:EXTRA_STATES.find(x=>x.key===s.key)||null})));let result=await buildScreens(figma,STATE,BATCH);routeMap=new Map(result.links.map(l=>[l.from,l.target]));document.addEventListener('click',routeClick);document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-target],[data-system]')){e.preventDefault();e.target.click()}});
 if(document.body.dataset.capture==='true'){let grid=document.getElementById('capture-grid');for(let theme of ['light','dark'])for(const spec of all){let wrap=document.createElement('section');wrap.className='capture-item';let heading=document.createElement('h2');heading.textContent=`${theme} / ${spec.title} · ${spec.key}`;wrap.appendChild(heading);let host=document.createElement('div');host.className='capture-phone';wrap.appendChild(host);let model=page.children.find(n=>n.name===theme+'/'+spec.key);let el=render(model,host);el.style.left='0';el.style.top='0';grid.appendChild(wrap)}document.body.dataset.ready='true';return}
 const mobileSelect=document.getElementById('mobile-page');for(const spec of all){const option=document.createElement('option');option.value=spec.key;option.textContent=spec.title;mobileSelect.appendChild(option)}mobileSelect.addEventListener('change',()=>go(mobileSelect.value));let list=document.getElementById('page-list');for(const [i,spec] of all.entries()){if(i===core.length){let h=document.createElement('h3');h.textContent='补充状态';list.appendChild(h)}let b=document.createElement('button');b.className='page-link';b.dataset.page=spec.key;b.textContent=spec.title;b.addEventListener('click',()=>go(spec.key));list.appendChild(b)}document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>go(current,b.dataset.themeChoice)));document.querySelectorAll('[data-flow]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.flow)));let parts=location.hash.slice(1).split('/');if(['light','dark'].includes(parts[0])&&lookup.has(parts[1])){currentTheme=parts[0];current=parts[1]}showCurrent();sizePhone();window.addEventListener('resize',sizePhone);document.body.dataset.ready='true';}
init().catch(e=>{console.error(e);document.body.dataset.error=e.message;document.body.insertAdjacentHTML('afterbegin','<pre class="fatal">原型载入失败：'+String(e)+'</pre>')});
